  local sh,ch=math.sin(headingRadians),math.cos(headingRadians)
  local yaw,pitch=math.rad(view.yaw or 30),math.rad(view.pitch or 25)
  local sy,cyaw,sp,cp=math.sin(yaw),math.cos(yaw),math.sin(pitch),math.cos(pitch)
