function M.coordinates(text,kind)
  local values={}
  for token in tostring(text):gmatch("[^,%s;()]+") do
    local value=tonumber(token)
    if not addon.finite(value) then return nil,"Coordonnee invalide" end
    values[#values+1]=value
  end
